import React, { useState } from "react";
import "./schedule.css";

const Schedule = () => {
  const [teamName, setTeamName] = useState("");
  const [teams, setTeams] = useState([]);
  const [stage, setStage] = useState("League");
  const [timeSlot, setTimeSlot] = useState("Morning (9 AM - 12 PM)");
  const [matches, setMatches] = useState([]);

  const addTeam = () => {
    if (teamName.trim()) {
      setTeams([...teams, teamName.trim()]);
      setTeamName("");
    }
  };

  const generateMatches = () => {
    let generated = [];

    if (stage === "League") {
      for (let i = 0; i < teams.length; i++) {
        for (let j = i + 1; j < teams.length; j++) {
          generated.push({
            team1: teams[i],
            team2: teams[j],
            stage,
            timeSlot
          });
        }
      }
    } else {
      for (let i = 0; i < teams.length; i += 2) {
        if (teams[i + 1]) {
          generated.push({
            team1: teams[i],
            team2: teams[i + 1],
            stage,
            timeSlot
          });
        }
      }
    }

    setMatches(generated);
  };

  return (
    <div className="schedule-container">
      <h1 className="title">🏆 Tournament Schedule</h1>

      <div className="card">
        <input
          type="text"
          placeholder="Enter Team Name"
          value={teamName}
          onChange={(e) => setTeamName(e.target.value)}
        />
        <button onClick={addTeam}>Add Team</button>

        <div className="teams">
          {teams.map((t, i) => (
            <span key={i} className="team-chip">{t}</span>
          ))}
        </div>

        {/* Tournament Stage */}
        <select value={stage} onChange={(e) => setStage(e.target.value)}>
          <option>League</option>
          <option>Qualifier</option>
          <option>Semi Final</option>
          <option>Final</option>
          <option>Knockout</option>
        </select>

        {/* Time Period */}
        <select value={timeSlot} onChange={(e) => setTimeSlot(e.target.value)}>
          <option>Morning (9 AM - 12 PM)</option>
          <option>Afternoon (1 PM - 4 PM)</option>
          <option>Evening (5 PM - 8 PM)</option>
          <option>Night (8 PM - 11 PM)</option>
        </select>

        <button className="generate" onClick={generateMatches}>
          Generate Schedule
        </button>
      </div>

      {matches.length > 0 && (
        <div className="table-wrapper">
          <table className="schedule-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Team A</th>
                <th>Team B</th>
                <th>Stage</th>
                <th>Time Slot</th>
              </tr>
            </thead>
            <tbody>
              {matches.map((m, i) => (
                <tr key={i}>
                  <td>{i + 1}</td>
                  <td>{m.team1}</td>
                  <td>{m.team2}</td>
                  <td>{m.stage}</td>
                  <td>{m.timeSlot}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Schedule;
